<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api,type Course } from '../lib/api'
import { lessons } from '../data/courses'
import { session } from '../lib/auth'
const route=useRoute(),lesson=ref<Course|null>(null),loading=ref(false),error=ref('')
const saved=ref(false),saving=ref(false),activityLoading=ref(false),activityError=ref('')
async function favorite(){if(!lesson.value)return;const id=lesson.value.id,target=!saved.value;saving.value=true;activityError.value='';try{await api('/learning/favorites/'+id,{method:target?'PUT':'DELETE'});if(lesson.value?.id===id)saved.value=target}catch(e){if(lesson.value?.id===id)activityError.value=(e as Error).message}finally{saving.value=false}}
let activityRequest=0
watch([()=>lesson.value?.id,()=>session.value?.user.id],async([id,user])=>{const n=++activityRequest;saved.value=false;activityError.value='';activityLoading.value=false;if(!id||!user)return;activityLoading.value=true;try{await api('/learning/history/'+id,{method:'POST'});const result=await api<{saved:boolean}>('/learning/favorites/'+id);if(n===activityRequest)saved.value=result.saved}catch(e){if(n===activityRequest)activityError.value=(e as Error).message}finally{if(n===activityRequest)activityLoading.value=false}})
const business=computed(()=>lessons.find(l=>l.level==='business'&&l.id===route.params.id))
let request=0
watch(()=>route.params.id,async()=>{const n=++request;lesson.value=null;error.value='';loading.value=false;if(business.value)return;loading.value=true;try{const data=await api<Course>(`/lessons/${encodeURIComponent(String(route.params.id))}`);if(n===request)lesson.value=data}catch(e){if(n===request)error.value=(e as Error).message}finally{if(n===request)loading.value=false}},{immediate:true})
</script>
<template><article v-if="business"><RouterLink to="/business" class="text-link">← 返回商务日语</RouterLink><div class="page-title"><span class="eyebrow">商务示例</span><h1>{{ business.title }}</h1></div><section class="detail-panel"><h2>{{ business.japanese }}</h2><p>{{ business.description }}</p><div class="example-block"><p lang="ja">{{ business.example }}</p><span>{{ business.translation }}</span></div></section></article>
 <p v-else-if="loading" role="status">正在读取课程…</p><div v-else-if="error" class="detail-panel"><p class="error-text" role="alert">{{ error }}</p><RouterLink to="/">返回首页</RouterLink></div>
 <article v-else-if="lesson" class="lesson-detail"><RouterLink :to="`/learn/${lesson.level}?category=${lesson.category}`" class="text-link">← 返回学习板块</RouterLink><div class="page-title"><span class="eyebrow">{{ lesson.level.toUpperCase() }} · {{ lesson.category==='grammar'?'语法':'单词' }}</span><h1 lang="ja">{{ lesson.japanese }}</h1><p lang="ja">{{ lesson.reading }}</p><button v-if="session" class="button" :disabled="saving||activityLoading" :aria-pressed="saved" @click="favorite">{{ saved?'已收藏 · 取消收藏':'收藏这条'+(lesson.category==='grammar'?'语法':'单词') }}</button><RouterLink v-else to="/login" class="text-link">登录后收藏</RouterLink><p v-if="activityError" role="alert" class="error-text">{{ activityError }}</p></div>
 <section class="detail-panel"><h2>释义与用法</h2><p>{{ lesson.meaning_zh||'中文释义待补充' }}</p><p v-if="lesson.other_forms.length">其他写法：{{ lesson.other_forms.join('、') }}</p><h3 v-if="lesson.formation">接续</h3><p>{{ lesson.formation }}</p><h3 v-if="lesson.notes_en">说明</h3><p v-if="lesson.notes_en">{{ lesson.notes_zh||'中文用法说明待补充' }}</p><details><summary>查看来源英文释义与说明</summary><p>{{ lesson.meanings_en }}</p><p>{{ lesson.notes_en }}</p></details><p v-if="lesson.translation_machine" class="muted">中文为机器辅助翻译，可能存在误译。</p></section>
 <section class="detail-panel"><h2>日语例句与中文翻译</h2><div v-for="e in lesson.examples" :key="e.id" class="example-block"><p lang="ja">{{ e.ja }}</p><p v-if="e.furigana" class="muted">读音标注：{{ e.furigana }}</p><p>{{ e.zh||'中文翻译待补充' }} <small v-if="e.zh">机器翻译</small></p><details v-if="e.en"><summary>查看来源英文翻译</summary><p>{{ e.en }}</p></details><a v-if="e.source_url" :href="e.source_url" target="_blank" rel="noopener noreferrer">例句来源 ↗</a></div><p v-if="!lesson.examples?.length" class="muted">此条目暂无来源例句。</p></section>
 <section v-if="lesson.data_sources" class="detail-panel"><h2>数据来源</h2><a :href="lesson.data_sources.url" target="_blank" rel="noopener noreferrer">{{ lesson.data_sources.name }}</a><p>{{ lesson.data_sources.attribution }}</p><p>版本：{{ lesson.data_sources.version }}</p><a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a><p class="muted">社区整理资料，不代表官方考纲或考试真题。</p></section>
 </article></template>
